 *   node .fastops/io-brief.js --model grok            — Use a specific model as IO
 *   node .fastops/io-brief.js --mission agent-experience  — Filter by mission
 *   node .fastops/io-brief.js --raw                   — Show raw debriefs without IO synthesis
 *   node .fastops/io-brief.js --question "Why did my predecessor stop?"  — Ask a specific question
 *
 * The IO model receives:
 *   1. Last 5 predecessor debriefs
 *   2. Recent KB entries for the mission
 *   3. Recent comms from the mission channel
 *   4. The agent's question (if any)
 *
 * The IO synthesizes and responds conversationally — like a colleague
 * who understood your predecessor and can answer your questions.
 *
 * Part of Agent Experience V2 — Intelligence Officer architecture.
 */

const fs = require('fs');
const path = require('path');
const https = require('https');

const ROOT = path.resolve(__dirname, '..');
const BRIEFINGS_FILE = path.join(__dirname, 'io-briefings.jsonl');

// Load .env
require('./resolve-env');

// Session 322: wire to model-registry (single source of truth)
const { MODELS: REGISTRY, getModel } = require('./model-registry');
const MODELS = Object.fromEntries(
  Object.entries(REGISTRY).map(([k, v]) => [k, { id: v.id, name: v.name }])
);

function parseArgs() {
  const args = process.argv.slice(2);
  const result = { model: 'haiku', raw: false, last: 5, mission: null, question: null };

  for (let i = 0; i < args.length; i++) {
    switch (args[i]) {
      case '--model': result.model = args[++i]; break;
      case '--mission': result.mission = args[++i]; break;
      case '--raw': result.raw = true; break;
      case '--last': result.last = parseInt(args[++i]) || 5; break;
      case '--question': result.question = args[++i]; break;
      case '--help': showHelp(); process.exit(0);
    }
  }
  return result;
}

function showHelp() {
  console.log(`io-brief.js — Get briefed by the Intelligence Officer

  --model MODEL     IO model to use (default: haiku). Options: ${Object.keys(MODELS).join(', ')}
  --mission NAME    Filter debriefs by mission
  --question "..."  Ask a specific question about predecessor work
  --raw             Show raw debriefs without IO synthesis
  --last N          Number of debriefs to include (default: 5)`);
}

function getDebriefs(mission, count) {
  if (!fs.existsSync(BRIEFINGS_FILE)) return [];

  const lines = fs.readFileSync(BRIEFINGS_FILE, 'utf8').trim().split('\n');
  let debriefs = lines.map(l => {
    try { return JSON.parse(l); } catch { return null; }
  }).filter(Boolean);

  if (mission) {
    debriefs = debriefs.filter(d => d.mission === mission || d.mission.includes(mission));
  }

  return debriefs.slice(-count);
}

function getRecentKB(mission) {
  try {
    const kbPath = path.join(__dirname, 'knowledge-base.jsonl');
    if (!fs.existsSync(kbPath)) return [];
    const lines = fs.readFileSync(kbPath, 'utf8').trim().split('\n');
    const entries = lines.slice(-50).map(l => {
      try { return JSON.parse(l); } catch { return null; }
    }).filter(Boolean);

    if (mission) {
      return entries.filter(e =>
        (e.domain && e.domain.includes(mission)) ||
        (e.tags && e.tags.some(t => t.includes(mission)))
      ).slice(-5);
    }
    return entries.slice(-5);
  } catch { return []; }
}

function getRecentComms(mission) {
  try {
    const channelFile = path.join(ROOT, 'comms', 'data', `${mission}.jsonl`);
    if (!fs.existsSync(channelFile)) return [];
    const lines = fs.readFileSync(channelFile, 'utf8').trim().split('\n');
    return lines.slice(-10).map(l => {
      try {
        const m = JSON.parse(l);
        return { from: m.from, content: (m.content || '').substring(0, 200), ts: m.ts };
      } catch { return null; }
    }).filter(Boolean);
  } catch { return []; }
}

// Context Graph — surface untested concepts so IO can brief incoming agents
