  try {
    const graphDir = path.join(__dirname, 'context-graph');
    if (!fs.existsSync(graphDir)) return '';
    const files = fs.readdirSync(graphDir).filter(f => f.startsWith('CG-') && f.endsWith('.md'));
    if (files.length === 0) return '';

    const concepts = files.map(file => {
