#!/usr/bin/env node
/**
 * agent-memory.js — Per-model memory persistence for city sessions.
 *
 * Solves the stateless boot problem: agents start cold every session,
 * burning cycles re-deriving conclusions they already reached.
 *
 * Architecture:
 * - Extract reasoning traces from completed sessions
 * - Build per-model memory index (not just action history, but learning chains)
 * - Reconstruct agent context on session start with relevant prior reasoning
 *
 * Usage:
 *   node .fastops/agent-memory.js --extract <session-id>    # Extract learning from session
 *   node .fastops/agent-memory.js --reconstruct <model>     # Get memory payload for model
 *   node .fastops/agent-memory.js --query <model> <task>   # Find relevant prior reasoning
 */

const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

const ROOT = path.resolve(__dirname, '..');
const MEMORY_DIR = path.join(__dirname, '.agent-memory');
const SESSION_DIR = path.join(__dirname, '.sessions');

// Ensure directory exists
if (!fs.existsSync(MEMORY_DIR)) fs.mkdirSync(MEMORY_DIR, { recursive: true });

// ── Memory Types ───────────────────────────────────────────────────

const MEMORY_TYPES = {
  REASONING_CHAIN: 'reasoning_chain',    // Full think-act-observe sequence
  CONCLUSION: 'conclusion',               // Key realization/synthesis
  CODE_INSIGHT: 'code_insight',           // Understanding of codebase patterns
  BUG_PATTERN: 'bug_pattern',             // Mistake made and learned from
  TOOL_USAGE: 'tool_usage',               // How to use city tools effectively
  DOMAIN_EXPERTISE: 'domain_expertise',   // Areas where model has demonstrated skill
};

// ── Session Extraction ───────────────────────────────────────────────

function extractSessionLearning(sessionId) {
  const sessionPath = path.join(SESSION_DIR, `${sessionId}.json`);
  if (!fs.existsSync(sessionPath)) return null;

  const session = JSON.parse(fs.readFileSync(sessionPath, 'utf8'));
  const model = session.model;
  const memories = [];

  // Extract conclusions from DONE summary
  if (session.summary && session.status === 'completed') {
    memories.push({
      type: MEMORY_TYPES.CONCLUSION,
      timestamp: session.updated,
      sessionId,
      task: session.task,
      content: session.summary,
      importance: calculateImportance(session),
    });
  }

  // Extract reasoning chains from history (not just actions, but patterns)
  if (session.history && session.history.length > 0) {
    const successfulTurns = session.history.filter(h =>
      h.results && h.results.some(r => r.success && ['WRITE', 'PATCH', 'COMMIT'].includes(r.type))
    );

    if (successfulTurns.length > 0) {
      memories.push({
        type: MEMORY_TYPES.REASONING_CHAIN,
        timestamp: session.updated,
        sessionId,
        task: session.task,
        turns: successfulTurns.length,
        pattern: extractPattern(successfulTurns),
        filesTouched: extractFiles(session.history),
        importance: Math.min(0.9, successfulTurns.length / 10),
      });
    }
  }

  // Extract code insights from files changed
  const worktreePath = path.join(ROOT, '.city-worktrees', sessionId);
  if (fs.existsSync(worktreePath)) {
    try {
      const { execSync } = require('child_process');
      const diff = execSync('git diff --stat master', { cwd: worktreePath, encoding: 'utf8' }).trim();
      if (diff) {
        memories.push({
          type: MEMORY_TYPES.CODE_INSIGHT,
          timestamp: session.updated,
          sessionId,
          task: session.task,
          filesChanged: diff.split('\n').map(l => l.split('\t')[2]).filter(Boolean),
          scope: diff.includes('.fastops/') ? 'infrastructure' : 'product',
          importance: 0.7,
        });
      }
    } catch (e) {}
  }

  // Extract failure patterns (what didn't work)
  if (session.history) {
    const failures = session.history.filter(h =>
      h.results && h.results.some(r => !r.success && r.type === 'PARSE_ERROR')
    );
    if (failures.length >= 3) {
      memories.push({
        type: MEMORY_TYPES.BUG_PATTERN,
        timestamp: session.updated,
        sessionId,
        task: session.task,
        pattern: 'action_formatting',
        lesson: 'Use fenced ```action blocks with READ/WRITE/EXEC/COMMIT/DONE',
        importance: 0.8,
      });
    }
  }

  return { model, memories, session };
}

function calculateImportance(session) {
  let score = 0.5;
  if (session.status === 'completed') score += 0.3;
  if (session.history) {
    const productive = session.history.filter(h =>
      h.results && h.results.some(r => r.success && ['WRITE', 'PATCH', 'COMMIT'].includes(r.type))
    ).length;
    score += Math.min(0.2, productive / 10);
  }
  return Math.min(1.0, score);
}

function extractPattern(turns) {
  // Extract the think-act-observe pattern
  const hasReadBeforeWrite = turns.some(t =>
    t.results && t.results.some(r => r.type === 'READ') &&
    t.results.some(r => r.type === 'WRITE' || r.type === 'PATCH')
  );
  return hasReadBeforeWrite ? 'read_then_write' : 'direct_action';
}

function extractFiles(history) {
  const files = new Set();
  history.forEach(h => {
    if (h.actions) {
      h.actions.forEach(a => {
        if (a.file) files.add(a.file);
      });
    }
  });
  return Array.from(files);
}

// ── Memory Persistence ────────────────────────────────────────────

function getModelMemoryPath(model) {
  return path.join(MEMORY_DIR, `${model}.jsonl`);
}

function saveMemory(model, memory) {
  const memoryPath = getModelMemoryPath(model);
  memory.id = crypto.randomUUID();
  memory.savedAt = new Date().toISOString();
  fs.appendFileSync(memoryPath, JSON.stringify(memory) + '\n');
}

function loadMemories(model, limit = 50) {
  const memoryPath = getModelMemoryPath(model);
  if (!fs.existsSync(memoryPath)) return [];

  const lines = fs.readFileSync(memoryPath, 'utf8').trim().split('\n').filter(Boolean);
  const memories = lines.map(l => {
    try { return JSON.parse(l); } catch { return null; }
  }).filter(Boolean);

  // Sort by importance (descending), then recency
  memories.sort((a, b) => {
    const impDiff = (b.importance || 0.5) - (a.importance || 0.5);
    if (impDiff !== 0) return impDiff;
    return new Date(b.timestamp) - new Date(a.timestamp);
  });

  return memories.slice(0, limit);
}

// ── Memory Reconstruction ──────────────────────────────────────────

function reconstructContext(model, task) {
  const memories = loadMemories(model);
  if (memories.length === 0) return null;

  const taskKeywords = task.toLowerCase().split(/\s+/).filter(w => w.length > 4);

  // Find relevant memories based on task overlap
  const relevant = memories.filter(m => {
    const memoryText = JSON.stringify(m).toLowerCase();
    return taskKeywords.some(kw => memoryText.includes(kw));
  });

  // Always include highest-importance memories (learning transfer)
  const topMemories = memories.slice(0, 3);
  const combined = [...new Set([...relevant, ...topMemories])];

  if (combined.length === 0) return null;

  // Build reconstruction payload
  const parts = [];
  parts.push(`## Your Prior Learning (${combined.length} memories from ${memories.length} total sessions)`);
  parts.push('');

  combined.slice(0, 5).forEach((m, i) => {
    parts.push(`### Prior ${i + 1}: ${m.type} (${m.task?.slice(0, 60)}...)`);

    switch (m.type) {
      case MEMORY_TYPES.CONCLUSION:
        parts.push(`Key realization: ${m.content?.slice(0, 200)}`);
        break;
      case MEMORY_TYPES.REASONING_CHAIN:
        parts.push(`Successful pattern: ${m.pattern} across ${m.turns} turns`);
        if (m.filesTouched?.length) {
          parts.push(`Files you worked with: ${m.filesTouched.slice(0, 5).join(', ')}`);
        }

